function Helper.NewInstantFinishHeist()
    if GTA.IsScriptRunning(eScript.Heist.Old) then
        GTA.ForceScriptHost(eScript.Heist.Old)
        Script.Yield(1000)

        eLocal.Heist.Generic.Finish.Old.Step1:Set(5)
        eLocal.Heist.Generic.Finish.Old.Step2:Set(999999)

        local value = Bits.SetBits(eLocal.Heist.Generic.Finish.Old.Step3:Get(), { 9, 16 })
        eLocal.Heist.Generic.Finish.Old.Step3:Set(value)
    elseif GTA.IsScriptRunning(eScript.Heist.New) then
        GTA.ForceScriptHost(eScript.Heist.New)
        Script.Yield(1000)

        eLocal.Heist.Generic.Finish.New.Step1:Set(5)
        eLocal.Heist.Generic.Finish.New.Step2:Set(999999)

        local value = Bits.SetBits(eLocal.Heist.Generic.Finish.New.Step3:Get(), { 9, 16 })
        eLocal.Heist.Generic.Finish.New.Step3:Set(value)
    end
end

function Helper.GetWeeklyMultiplierForJob(job)
    local function ShouldApplyWeeklyMultiplier()
        if eTunable.Heist.Generic.WeeklyMultiplier.Disabled:Get() then
            return false
        end

        if ScriptGlobal.GetBool(eGlobal.Heist.Generic.WeeklyMultiplier.JobsArray.global + job) then
            return false
        end

        return not Bits.IsBitSet(eGlobal.Heist.Generic.WeeklyMultiplier.Flag2:Get(), job)
    end

    local multipliers = {
        [0]  = eTunable.Heist.Generic.WeeklyMultiplier.Apartment.Fleeca:Get(),
        [2]  = eTunable.Heist.Generic.WeeklyMultiplier.Apartment.Prison:Get(),
        [1]  = eTunable.Heist.Generic.WeeklyMultiplier.Apartment.Humane:Get(),
        [3]  = eTunable.Heist.Generic.WeeklyMultiplier.Apartment.Series:Get(),
        [4]  = eTunable.Heist.Generic.WeeklyMultiplier.Apartment.Pacific:Get(),
        [5]  = eTunable.Heist.Generic.WeeklyMultiplier.Facility.Data:Get(),
        [6]  = eTunable.Heist.Generic.WeeklyMultiplier.Facility.Bogdan:Get(),
        [7]  = eTunable.Heist.Generic.WeeklyMultiplier.Facility.Doomsday:Get(),
        [8]  = eTunable.Heist.Generic.WeeklyMultiplier.DiamondCasino:Get(),
        [9]  = eTunable.Heist.Generic.WeeklyMultiplier.Agency:Get(),
        [10] = eTunable.Heist.Generic.WeeklyMultiplier.CluckinBell:Get(),
        [11] = eTunable.Heist.Generic.WeeklyMultiplier.GuzmanFlies:Get()
    }

    if eNative.NETWORK.NETWORK_IS_ACTIVITY_SESSION() then
        if Bits.IsBitSet(eGlobal.Heist.Generic.WeeklyMultiplier.Flag1:Get(), 27) then
            return multipliers[job]
        end
    elseif ShouldApplyWeeklyMultiplier(job) then
        return multipliers[job]
    end

    return 1.0
end

function Helper.SetApartmentMaxPayout(bool)
    local heist  = eStat.MPX_HEIST_MISSION_RCONT_ID_0:Get()
    local heists = eTable.Heist.Apartment.Data

    local payouts = {
        [heists.FleecaJob.RcontIDs[1]]   = eTunable.Heist.Apartment.Payout.Fleeca:Get(),
        [heists.PrisonBreak.RcontIDs[1]] = eTunable.Heist.Apartment.Payout.Prison:Get(),
        [heists.HumaneLabs.RcontIDs[1]]  = eTunable.Heist.Apartment.Payout.Humane:Get(),
        [heists.SeriesA.RcontIDs[1]]     = eTunable.Heist.Apartment.Payout.Series:Get(),
        [heists.PacificJob.RcontIDs[1]]  = eTunable.Heist.Apartment.Payout.Pacific:Get()
    }

    local activePayout = payouts[heist]

    if activePayout == nil then return end

    local function GetDifficultyMultiplier()
        local difficulty = eGlobal.Heist.Generic.Difficulty:Get()

        local multipliers = {
            [0] = eTunable.Heist.Apartment.DifficultyMultiplier.Easy:Get(),
            [1] = eTunable.Heist.Apartment.DifficultyMultiplier.Normal:Get(),
            [2] = eTunable.Heist.Apartment.DifficultyMultiplier.Hard:Get()
        }

        return multipliers[difficulty]
    end

    local jobs = {
        [heists.FleecaJob.RcontIDs[1]]   = 0,
        [heists.PrisonBreak.RcontIDs[1]] = 2,
        [heists.HumaneLabs.RcontIDs[1]]  = 1,
        [heists.SeriesA.RcontIDs[1]]     = 3,
        [heists.PacificJob.RcontIDs[1]]  = 4
    }

    local activeJob = jobs[heist]
    local fPayout   = math.floor(activePayout * Helper.GetWeeklyMultiplierForJob(activeJob) + 0.5)
    local payout    = math.floor(fPayout * GetDifficultyMultiplier())
    local maxPayout = 3000000
    local cut       = math.floor(maxPayout / (payout / 100) / ((bool) and 2 or 1))

    for i = 1, #apartmentPlayers.Cuts do
        FeatureMgr.GetFeature(apartmentPlayers.Cuts[i]):SetIntValue(cut)
    end
end

function Helper.SetCayoMaxPayout()
    local target = eStat.MPX_H4CNF_TARGET:Get()

    local payouts = {
        [0] = eTunable.Heist.CayoPerico.Payout.Tequila:Get(),
        [1] = eTunable.Heist.CayoPerico.Payout.Necklace:Get(),
        [2] = eTunable.Heist.CayoPerico.Payout.Bonds:Get(),
        [3] = eTunable.Heist.CayoPerico.Payout.Diamond:Get(),
        [4] = eTunable.Heist.CayoPerico.Payout.Files:Get(),
        [5] = eTunable.Heist.CayoPerico.Payout.Statue:Get()
    }

    local activePayout = payouts[target]

    if activePayout == nil then return end

    local function GetDifficultyMultiplier()
        if eStat.MPX_H4_PROGRESS:Get() & 4096 ~= 0 then
            return eTunable.Heist.CayoPerico.DifficultyMultiplier.Hard:Get()
        end

        return eTunable.Heist.CayoPerico.DifficultyMultiplier.Normal:Get()
    end

    local payout      = math.floor(activePayout * GetDifficultyMultiplier())
    local maxPayout   = 2550000
    local cut         = math.floor(maxPayout / (payout / 100))
    local finalPayout = math.floor(payout * (cut / 100))
    local difference  = 1000
    local pavelCut    = 0.02
    local fencingCut  = 0.1
    local foundCut    = false

    while not foundCut do
        local pavelFee   = math.floor(finalPayout * pavelCut)
        local fencingFee = math.floor(finalPayout * fencingCut)
        local feePayout  = finalPayout - (pavelFee + fencingFee)

        if feePayout >= maxPayout - difference and feePayout <= maxPayout then
            foundCut = true
        else
            cut         = cut + 1
            finalPayout = math.floor(payout * (cut / 100))

            if cut > 500 then
                cut         = math.floor(maxPayout / (payout / 100))
                finalPayout = math.floor(payout * (cut / 100))
                difference  = difference + 1000
            end
        end
    end

    for i = 1, #cayoPlayers.Cuts do
        FeatureMgr.GetFeature(cayoPlayers.Cuts[i]):SetIntValue(cut)
    end
end

function Helper.SetDiamondMaxPayout()
    eTunable.Heist.DiamondCasino.Buyer.Low:Set(1.0)
    eTunable.Heist.DiamondCasino.Buyer.Mid:Set(1.0)
    eTunable.Heist.DiamondCasino.Buyer.High:Set(1.0)

    local target = eStat.MPX_H3OPT_TARGET:Get()

    local payouts = {
        [0] = eTunable.Heist.DiamondCasino.Payout.Cash:Get(),
        [2] = eTunable.Heist.DiamondCasino.Payout.Arts:Get(),
        [1] = eTunable.Heist.DiamondCasino.Payout.Gold:Get(),
        [3] = eTunable.Heist.DiamondCasino.Payout.Diamonds:Get()
    }

    local activePayout = payouts[target]

    if activePayout == nil then return end

    local function GetDifficultyMultiplier()
        if eStat.MPX_H3OPT_APPROACH:Get() == eStat.MPX_H3_HARD_APPROACH:Get() then
            return eTunable.Heist.DiamondCasino.DifficultyMultiplier.Hard:Get()
        end

        return eTunable.Heist.DiamondCasino.DifficultyMultiplier.Normal:Get()
    end

    local activeJob = 8
    local fPayout   = math.floor(activePayout * Helper.GetWeeklyMultiplierForJob(activeJob) + 0.5)
    local payout    = math.floor(fPayout * GetDifficultyMultiplier()) + 819000
    local maxPayout = 3619000
    local cut       = math.floor(maxPayout / (payout / 100))

    FeatureMgr.GetFeature(diamondPlayers.Cuts[1]):SetIntValue(cut)

    if FeatureMgr.GetFeatureBool(eFeature.Heist.DiamondCasino.Launch.Solo) then return end

    local gunman    = eStat.MPX_H3OPT_CREWWEAP:Get()
    local driver    = eStat.MPX_H3OPT_CREWDRIVER:Get()
    local hacker    = eStat.MPX_H3OPT_CREWHACKER:Get()
    local buyer     = eGlobal.Heist.DiamondCasino.Board.Buyer:Get()
    local lesterCut = 0.05

    local buyerFees = {
        [0] = 0.1,
        [3] = 0.05,
        [6] = 0.0
    }

    local gunmanCuts = {
        [1] = 0.05,
        [3] = 0.07,
        [5] = 0.08,
        [2] = 0.09,
        [4] = 0.1
    }

    local driverCuts = {
        [1] = 0.05,
        [4] = 0.06,
        [2] = 0.07,
        [3] = 0.09,
        [5] = 0.1
    }

    local hackerCuts = {
        [1] = 0.03,
        [3] = 0.05,
        [2] = 0.07,
        [5] = 0.09,
        [4] = 0.1
    }

    local buyerFee  = buyerFees[buyer]
    local gunmanCut = gunmanCuts[gunman]
    local driverCut = driverCuts[driver]
    local hackerCut = hackerCuts[hacker]

    if buyerFee == nil then return end
    if gunmanCut == nil then return end
    if driverCut == nil then return end
    if hackerCut == nil then return end

    local feePayout    = math.floor(payout * (1.0 - buyerFee))
    local crewPayout   = math.floor(feePayout * (gunmanCut + driverCut + hackerCut + lesterCut))
    local cut          = math.floor(maxPayout / ((math.floor(feePayout - crewPayout)) / 100))

    for i = 2, #diamondPlayers.Cuts do
        FeatureMgr.GetFeature(diamondPlayers.Cuts[i]):SetIntValue(cut)
    end
end

function Helper.SetDoomsdayMaxPayout()
    local acts  = eTable.Heist.Doomsday.Heists
    local heist = eStat.MPX_GANGOPS_FLOW_MISSION_PROG:Get()

    local payouts = {
        [acts.Data]     = eTunable.Heist.Doomsday.Payout.ActI:Get(),
        [acts.Bogdan]   = eTunable.Heist.Doomsday.Payout.ActII:Get(),
        [acts.Doomsday] = eTunable.Heist.Doomsday.Payout.ActIII:Get()
    }

    local activePayout = payouts[heist]

    if activePayout == nil then return end

    local function GetDifficultyMultiplier()
        if eGlobal.Heist.Generic.Difficulty:Get() == 2 then
            return eTunable.Heist.Doomsday.Multiplier.Hard:Get()
        end

        return eTunable.Heist.Doomsday.Multiplier.Normal:Get()
    end

    local jobs = {
        [acts.Data]     = 5,
        [acts.Bogdan]   = 6,
        [acts.Doomsday] = 7
    }

    local activeJob = jobs[heist]
    local fPayout   = math.floor(activePayout * Helper.GetWeeklyMultiplierForJob(activeJob) + 0.5)
    local payout    = math.floor(fPayout * GetDifficultyMultiplier())
    local maxPayout = 2550000
    local cut       = math.floor(maxPayout / (payout / 100))

    for i = 1, #doomsdayPlayers.Cuts do
        FeatureMgr.GetFeature(doomsdayPlayers.Cuts[i]):SetIntValue(cut)
    end
end

