    FeatureMgr.GetFeature(eFeature.Heist.Doomsday.Cuts.Player4.Cut):SetIntValue(preps.player4.cut or 0)

    Script.Yield(500)
    CONFIG.logging = temp
end

function Helper.GetHangarCargoTypeFromCrateType(crateType)
    if crateType == -1 then
        return -1
    end

    local cargoTypes = {
        [11] = 0, [12] = 0,
        [5]  = 1, [6]  = 1,
        [15] = 2, [16] = 2,
        [13] = 3, [14] = 3,
        [9]  = 4, [10] = 4,
        [1]  = 5, [2]  = 5,
        [7]  = 6, [8]  = 6,
        [3]  = 7, [4]  = 7
    }

    return cargoTypes[crateType] or -1
end

function Helper.GetHangarAmountForCargoType(cargoType)
    if cargoType == 8 then
        return eStat.MPX_HANGAR_CONTRABAND_TOTAL:Get()
    end

    local amount   = 0
    local charSlot = eStat.MPPLY_LAST_MP_CHAR:Get()
    local startIdx = ePackedStat.Business.Hangar.Crate.First.index[1]
    local endIdx   = ePackedStat.Business.Hangar.Crate.Last.index[1]

    for i = startIdx, endIdx do
        local crateType = eNative.STATS.GET_PACKED_STAT_INT_CODE(i, charSlot)

        if Helper.GetHangarCargoTypeFromCrateType(crateType) == cargoType then
            amount = amount + 1
        end
    end

    return amount
end

function Helper.GetHangarWarehouseValue(forceMixed)
    local function GetPriceForCargoType(cargoType)
        local price = {
            [0] = eTunable.Business.Hangar.Price.Animal:Get(),
            [1] = eTunable.Business.Hangar.Price.Art:Get(),
            [2] = eTunable.Business.Hangar.Price.Chemicals:Get(),
            [3] = eTunable.Business.Hangar.Price.Goods:Get(),
            [4] = eTunable.Business.Hangar.Price.Gems:Get(),
            [5] = eTunable.Business.Hangar.Price.Meds:Get(),
            [6] = eTunable.Business.Hangar.Price.Narcotics:Get(),
            [7] = eTunable.Business.Hangar.Price.Tabacco:Get(),
            [8] = eTunable.Business.Hangar.Price.Mixed:Get(),
        }

        local multiplier = 1.0

        if Bits.IsBitSet(eGlobal.Business.Hangar.Bit:Get(), 2) then
            multiplier = eTunable.Business.Hangar.Multiplier:Get()
        end

        return math.floor((price[cargoType] * multiplier) + 0.5) or 0
    end

    local function GetBonusPercentageForCargoType(cargoType, amount)
        if cargoType == 8 then
            return 0.0
        end

        local percentage = {
            [0] = eTunable.Business.Hangar.Bonus.Percentage.Animal:Get(),
            [1] = eTunable.Business.Hangar.Bonus.Percentage.Art:Get(),
            [2] = eTunable.Business.Hangar.Bonus.Percentage.Chemicals:Get(),
            [3] = eTunable.Business.Hangar.Bonus.Percentage.Goods:Get(),
            [4] = eTunable.Business.Hangar.Bonus.Percentage.Gems:Get(),
            [5] = eTunable.Business.Hangar.Bonus.Percentage.Meds:Get(),
            [6] = eTunable.Business.Hangar.Bonus.Percentage.Narcotics:Get(),
            [7] = eTunable.Business.Hangar.Bonus.Percentage.Tabacco:Get(),
        }

        local threshold = {
            [0] = eTunable.Business.Hangar.Bonus.Threshhold.Animal:Get(),
            [1] = eTunable.Business.Hangar.Bonus.Threshhold.Art:Get(),
            [2] = eTunable.Business.Hangar.Bonus.Threshhold.Chemicals:Get(),
            [3] = eTunable.Business.Hangar.Bonus.Threshhold.Goods:Get(),
            [4] = eTunable.Business.Hangar.Bonus.Threshhold.Gems:Get(),
            [5] = eTunable.Business.Hangar.Bonus.Threshhold.Meds:Get(),
            [6] = eTunable.Business.Hangar.Bonus.Threshhold.Narcotics:Get(),
            [7] = eTunable.Business.Hangar.Bonus.Threshhold.Tabacco:Get(),
        }

        local rawPercentage   = percentage[cargoType]
        local cleanPercentage = math.floor((rawPercentage * 1000) + 0.5) / 1000

        return math.floor((amount + .0) / threshold[cargoType]) * cleanPercentage
    end

    if not ScriptGlobal.AreValid() then return 0 end

    local mixed       = 8
    local totalCrates = Helper.GetHangarAmountForCargoType(mixed)

    if forceMixed then
        return GetPriceForCargoType(mixed) * totalCrates
    end

    local value            = 0
    local uniqueTypesCount = 0
    local lastFoundType    = -1

    for i = 0, 7 do
        local amount = Helper.GetHangarAmountForCargoType(i)
        if amount > 0 then
            uniqueTypesCount = uniqueTypesCount + 1
            lastFoundType = i
        end
    end

    if uniqueTypesCount == 1 then
        local amount     = totalCrates
        local basePrice  = GetPriceForCargoType(lastFoundType) * amount
        local bonusPct   = GetBonusPercentageForCargoType(lastFoundType, amount)
        local bonusValue = math.floor((basePrice * bonusPct) + 0.5)

        value = basePrice + bonusValue
    elseif uniqueTypesCount > 1 then
        if totalCrates > 50 then
            return GetPriceForCargoType(mixed) * totalCrates
        end

        for i = 0, 7 do
            local amount = Helper.GetHangarAmountForCargoType(i)

            if amount > 0 then
                value = value + (GetPriceForCargoType(i) * amount)
            end
        end
    end

    return value
end

function Helper.FormatMoney(amount)
    local n = S(math.floor(math.abs(amount)))
    local f = n:reverse():gsub("%d%d%d", "%1,"):reverse():gsub("^,", "")
    return F("$%s%s", (amount < 0) and "-" or "", f)
end

function Helper.RefreshFiles()
    Utils.FillDynamicTables()
    Parser.ParseTables(eTable)
    FeatureMgr.GetFeature(eFeature.Heist.Apartment.Presets.File):SetList(eFeature.Heist.Apartment.Presets.File.list:GetNames()):SetListIndex(0)
    FeatureMgr.GetFeature(eFeature.Heist.CayoPerico.Presets.File):SetList(eFeature.Heist.CayoPerico.Presets.File.list:GetNames()):SetListIndex(0)
    FeatureMgr.GetFeature(eFeature.Heist.DiamondCasino.Presets.File):SetList(eFeature.Heist.DiamondCasino.Presets.File.list:GetNames()):SetListIndex(0)
    FeatureMgr.GetFeature(eFeature.Heist.Doomsday.Presets.File):SetList(eFeature.Heist.Doomsday.Presets.File.list:GetNames()):SetListIndex(0)
    FeatureMgr.GetFeature(eFeature.Settings.Translation.File):SetList(eFeature.Settings.Translation.File.list:GetNames()):SetListIndex(0)
    FeatureMgr.GetFeature(eFeature.Dev.Editor.Stats.File)
        :SetList(eFeature.Dev.Editor.Stats.File.list:GetNames())
        :SetDesc("Select the desired stat file.")
        :SetListIndex(0)
end

function Helper.IsPropertyOwned(property)
    if not GTA.IsInSession() then
        return false
    end

    if property == eTable.Properties.Warehouse then
        for i = 0, 4 do
            if eStat[F("MPX_WARHOUSESLOT%d", i)]:Get() ~= 0 then
                return true
            end

            return false
        end
    end

    return property:Get() ~= 0
end

function Helper.RegisterAsBoss()
    if not CONFIG.register_as_boss.autoregister then return end

    if eGlobal.Player.Organization.CEO:Get() == -1 then
        eGlobal.Player.Organization.CEO:Set(PLAYER_ID)
    end

    if eGlobal.Player.Organization.Type:Get() ~= CONFIG.register_as_boss.type then
        eGlobal.Player.Organization.Type:Set(CONFIG.register_as_boss.type)
    end
end

function Helper.RenderLaunchSettings(requiredPlayers, resetFeature)
    local reqPlayers = eLocal.Heist.Generic.Launch.Step2:Get()

    if reqPlayers ~= 0 and reqPlayers ~= requiredPlayers then
        local r, g, b, a = U(eBtnStyle.PINK.Hovered)
        ImGui.TextColored("Current State:", r, g, b, a, "Modified")
        ImGui.TextColored("Required Players:", r, g, b, a, S(reqPlayers))
        FeatureMgr.GetFeature(resetFeature):SetVisible(true)
    else
        local color = (reqPlayers ~= 0) and eBtnStyle.GREEN or eBtnStyle.ORANGE
        local r, g, b, a = U(color.Hovered)
        ImGui.TextColored("Current State:", r, g, b, a, (reqPlayers ~= 0) and "Standard" or "Default")
        ImGui.TextColored("Required Players:", r, g, b, a, S((reqPlayers ~= 0) and reqPlayers or "N/A"))
        FeatureMgr.GetFeature(resetFeature):SetVisible(false)
    end
end

