                    Apply = {
                        hash = J("SN_GuzmanFlies_Apply"),
                        name = "Apply Payout",
                        type = eFeatureType.Button,
                        desc = "Applies the selected payout. Use after you can see the minimap.",
                        func = function(payout)
                            local activeJob        = 11
                            local weeklyMultiplier = Helper.GetWeeklyMultiplierForJob(activeJob)

                            local function GetDifficultyMultiplier()
                                if ePackedStat.Heist.GuzmanFlies.HardMode:Get() then
                                    return eTunable.Heist.GuzmanFlies.DifficultyMultiplier.Hard:Get()
                                end

                                return 1.0
                            end

                            local difficultyMultiplier = GetDifficultyMultiplier()

                            local function GetBonusReward()
                                local charSlot    = eStat.MPPLY_LAST_MP_CHAR:Get()
                                local mogul       = ePackedStat.Heist.GuzmanFlies.Mogul.index[1]
                                local mules       = ePackedStat.Heist.GuzmanFlies.Mules.index[1]
                                local bonusReward = 0
                                local isHardMode  = ePackedStat.Heist.GuzmanFlies.HardMode:Get()

                                if eNative.STATS.GET_PACKED_STAT_BOOL_CODE(mogul, charSlot) then
                                    bonusReward = bonusReward + (isHardMode and 30000 or 20000)
                                end

                                if eNative.STATS.GET_PACKED_STAT_BOOL_CODE(mules, charSlot) then
                                    bonusReward = bonusReward + (isHardMode and 7500 or 5000)
                                else
                                    bonusReward = bonusReward - (isHardMode and 22500 or 15000)
                                end

                                if ePackedStat.Heist.GuzmanFlies.HeavyArmor:Get() then
                                    bonusReward = bonusReward + (isHardMode and 3750 or 2500)
                                end

                                if ePackedStat.Heist.GuzmanFlies.Insurgent:Get() then
                                    bonusReward = bonusReward + (isHardMode and 7500 or 5000)
                                end

                                if ePackedStat.Heist.GuzmanFlies.MogulUpgrades:Get() then
                                    bonusReward = bonusReward + (isHardMode and 7500 or 5000)
                                end

                                if ePackedStat.Heist.GuzmanFlies.WeaponCrate:Get() then
                                    bonusReward = bonusReward + (isHardMode and 3750 or 2500)
                                end

                                return bonusReward
                            end

                            local multiplier = GetDifficultyMultiplier() * weeklyMultiplier
                            local adjustedPayout = math.floor((payout - GetBonusReward()) / multiplier)

                            eTunable.Heist.GuzmanFlies.Payout:Set(adjustedPayout)
                            SilentLogger.LogInfo("[Apply Payout (Guzman Flies)] Payout should've been applied ツ")
                        end
                    }
                }
            }
