                            SilentLogger.LogInfo(F("[Pocket Dimension (Hangar)] Pocket Dimension should've been %s ツ", (ftr:IsToggled()) and "enabled" or "disabled"))
                        end
                    },

                    Fill = {
                        hash = J("SN_Hangar_Fill"),
                        name = "Fill",
                        type = eFeatureType.Button,
                        desc = "Almost instantly fills your Hangar stock with the preferred limit. Change the session to apply.",
                        func = function(limitByAmount, limit)
                            if GTA.IsScriptRunning(eScript.Hangar.Laptop) then
                                SilentLogger.LogError("[Fill (Hangar)] You must close Hangar computer's screen first ツ")
                                return
                            end

                            if GTA.IsScriptRunning(eScript.Hangar.Interior) then
                                SilentLogger.LogError("[Fill (Hangar)] You must leave your Hangar first ツ")
                                return
                            end

                            local stock = eStat.MPX_HANGAR_CONTRABAND_TOTAL:Get()

                            if stock > 0 then
                                SilentLogger.LogError("[Fill (Hangar)] You must remove all your stock first ツ")
                                return
                            end

                            local amount = (limitByAmount) and stock or Helper.GetHangarWarehouseValue(true)

                            if limit <= amount then
                                SilentLogger.LogError("[Fill (Hangar)] You must select a higher cargo limit ツ")
                                return
                            end

                            local multiplier = 1.0

                            if Bits.IsBitSet(eGlobal.Business.Hangar.Bit:Get(), 2) then
                                multiplier = eTunable.Business.Hangar.Multiplier:Get()
                            end

                            local price = math.floor((eTunable.Business.Hangar.Price.Mixed:Get() * multiplier) + 0.5)

                            if CONFIG.pocket_dimension.overflow_prevention then
                                if not limitByAmount then
                                    if limit > INT32_MAX then
                                        limit = INT32_MAX
                                        SilentLogger.LogInfo("[Fill (Hangar)] Overflow Prevention clamped value limit to $2,147,483,647 ツ")
                                    end
                                else
                                    local maxCrates = math.floor(INT32_MAX / price)

                                    if limit > maxCrates then
                                        limit = maxCrates
                                        SilentLogger.LogInfo(F("[Fill (Hangar)] Overflow Prevention clamped stock limit to %d crates ツ", maxCrates))
                                    end
                                end
                            end

                            PD_FILL_DISABLED   = true
                            PD_REMOVE_DISABLED = true

                            eGlobal.Business.Hangar.Cargo.Type:Set(3)
                            eGlobal.Business.Hangar.Cargo.Amount:Set(1)
                            ePackedStat.Business.Hangar.Cargo:Set(true)
                            Script.Yield(3000)

                            local targetCrates = limit

                            if not limitByAmount then
                                targetCrates = math.floor(limit / price)
                            end

                            local cratesToAdd = targetCrates - eStat.MPX_HANGAR_CONTRABAND_TOTAL:Get()

                            if cratesToAdd <= 0 then
                                PD_FILL_DISABLED   = false
                                PD_REMOVE_DISABLED = false
                                SilentLogger.LogError("[Fill (Hangar)] You must select a higher limit ツ")
                                return
                            end

                            operations1 = { -1723077437, 357925343,  0, 1, 1           }
                            operations2 = { 1673236337,  -1,         0, 3, cratesToAdd }
                            operations3 = { -576067948,  1673236337, 0, 1, 1           }

                            GTA.TriggerBasketTransaction(-1799524201, -1018905335, 4, { operations1 })
                            Script.Yield(3000)
                            GTA.TriggerBasketTransaction(-1799524201, 2108234284, 4, { operations1, operations2, operations3 })

                            local timeout = 0

                            while eStat.MPX_HANGAR_CONTRABAND_TOTAL:Get() ~= targetCrates + stock do
                                Script.Yield(1000)
                                timeout = timeout + 1
                                if timeout == CONFIG.timeout_duration then
                                    PD_FILL_DISABLED   = false
                                    PD_REMOVE_DISABLED = false
                                    SilentLogger.LogError("[Fill (Hangar)] Timed out waiting for stock to be filled. Try again later ツ")
                                    return
                                end
                            end

                            SilentLogger.LogInfo("[Fill (Hangar)] Hangar stock should've been filled. Change the session to apply ツ")
                        end
                    },

                    Remove = {
                        hash = J("SN_Hangar_Remove"),
                        name = "Remove",
                        type = eFeatureType.Button,
                        desc = "ATTENTION: cannot be undone.\nAlmost instantly removes all your Hangar stock. Change the session to apply.",
                        func = function()
                            local stock = eStat.MPX_HANGAR_CONTRABAND_TOTAL:Get()

                            if stock == 0 then
                                SilentLogger.LogError("[Remove (Hangar)] You must have stock to remove ツ")
                                return
                            end

                            PD_START_DISABLED   = true
                            PD_FILL_DISABLED   = true
                            PD_REMOVE_DISABLED = true

                            operations1 = { -1723077437, 244232650,  0, 1, 1     }
                            operations2 = { 1673236337,  -1,         0, 3, stock }
                            operations3 = { -1717954949, 1673236337, 0, 0, 1     }

                            GTA.TriggerBasketTransaction(-1799524201, -1018905335, 4, { operations1 })
                            Script.Yield(3000)
                            GTA.TriggerBasketTransaction(-1799524201, -788753717, 4, { operations1, operations2, operations3 })

                            local timeout = 0

                            while eStat.MPX_HANGAR_CONTRABAND_TOTAL:Get() ~= 0 do
                                Script.Yield(1000)
                                timeout = timeout + 1
                                if timeout == CONFIG.timeout_duration then
                                    PD_START_DISABLED  = false
                                    PD_FILL_DISABLED   = false
                                    PD_REMOVE_DISABLED = false
                                    SilentLogger.LogError("[Remove (Hangar)] Timed out waiting for stock to be removed. Try again later ツ")
                                    return
                                end
                            end

                            SilentLogger.LogInfo("[Remove (Hangar)] Hangar stock should've been removed. Change the session to apply ツ")
                        end
                    },

                    Session = {
                        hash = J("SN_Hangar_Session"),
                        name = "Change Session",
                        type = eFeatureType.Button,
                        desc = "Changes your session to a new invite only session.",
                        func = function()
                            GTA.StartSession(eTable.Session.Types.Invite)
                            SilentLogger.LogInfo("[Change Session (Hangar)] Session should've been changed ツ")
                        end
                    },

                    StartStop = {
                        hash = J("SN_Hangar_Start"),
                        name = "Start",
                        type = eFeatureType.Toggle,
                        desc = "Starts filling your Hangar stock repeatedly.",
                        func = function(ftr, limitToggled, limitByAmount, limit, step, type, delay)
                            if not ftr:IsToggled() then
                                ftr:SetName("Start")
                                ftr:SetDesc("Starts filling your Hangar stock repeatedly.")

                                while eNative.NETSHOPPING.NET_GAMESERVER_TRANSACTION_IN_PROGRESS() do
                                    Script.Yield()
                                end

                                Script.Yield(1000)

                                eGlobal.Business.Hangar.Cargo.Total:Set(eStat.MPX_HANGAR_CONTRABAND_TOTAL:Get())

                                if loggedHangarStart then
                                    SilentLogger.LogInfo("[Stop (Hangar)] Deeper supplier should've been disabled ツ")
                                    loggedHangarStart = false
                                end

                                PD_REMOVE_DISABLED = false
                                return
                            end

                            if GTA.IsScriptRunning(eScript.Hangar.Laptop) then
                                SilentLogger.LogError("[Fill (Hangar)] You must close Hangar computer's screen first ツ")
                                ftr:Toggle(false)
                                return
                            end

                            if GTA.IsScriptRunning(eScript.Hangar.Interior) then
                                SilentLogger.LogError("[Fill (Hangar)] You must leave your Hangar first ツ")
                                ftr:Toggle(false)
                                return
                            end

                            local uniqueCargoTypes = 0

                            for i = 0, 7 do
                                local amount = Helper.GetHangarAmountForCargoType(i)
                                if amount > 0 then
                                    uniqueCargoTypes = uniqueCargoTypes + 1
                                end
                            end

                            local cargoTotal = eStat.MPX_HANGAR_CONTRABAND_TOTAL:Get()
                            local maxCargo   = 50
                            local altType    = (type == 0) and type + 1 or type - 1

                            if uniqueCargoTypes < 2 then
                                if cargoTotal >= maxCargo then
                                    SilentLogger.LogError("[Start (Hangar)] You must remove all your stock first ツ")
                                    ftr:Toggle(false)
                                    return
                                else
                                    if Helper.GetHangarAmountForCargoType(altType) == 0 then
                                        type = altType
                                        step = 1
                                    end
                                end
                            end

                            local multiplier = 1.0

                            if Bits.IsBitSet(eGlobal.Business.Hangar.Bit:Get(), 2) then
                                multiplier = eTunable.Business.Hangar.Multiplier:Get()
                            end

                            local price = math.floor((eTunable.Business.Hangar.Price.Mixed:Get() * multiplier) + 0.5)

                            if CONFIG.pocket_dimension.overflow_prevention then
                                local currentValue = Helper.GetHangarWarehouseValue(true)
                                local room         = INT32_MAX - currentValue

                                if room <= 0 or price <= 0 then
                                    eGlobal.Business.Hangar.Cargo.Total:Set(eStat.MPX_HANGAR_CONTRABAND_TOTAL:Get())
                                    SilentLogger.LogInfo("[Start (Hangar)] Overflow Prevention reached INT32_MAX value ツ")
                                    ftr:Toggle(false)
                                    return
                                end

                                local maxStep = math.floor(room / price)

                                if maxStep <= 0 then
                                    eGlobal.Business.Hangar.Cargo.Total:Set(eStat.MPX_HANGAR_CONTRABAND_TOTAL:Get())
                                    SilentLogger.LogInfo("[Start (Hangar)] Overflow Prevention reached INT32_MAX value ツ")
                                    ftr:Toggle(false)
                                    return
                                end

                                if step > maxStep then
                                    step = maxStep
                                end

                                if not limitToggled then
                                    limitToggled  = true
                                    limitByAmount = false
                                    limit         = INT32_MAX
                                elseif not limitByAmount then
                                    if limit == 0 or limit > INT32_MAX then
                                        limit = INT32_MAX
                                    end
                                else
                                    local maxCrates = math.floor(INT32_MAX / price)

                                    if limit == 0 or limit > maxCrates then
                                        limit = maxCrates
                                    end
                                end
                            end

                            if limitToggled then
                                if limitByAmount and (limit ~= 0) and (cargoTotal + step) >= limit then
                                    step = limit - cargoTotal
                                end

                                if not limitByAmount and (limit ~= 0) then
                                    limit = math.floor(limit / price)

                                    if (cargoTotal + step) >= limit then
                                        step = limit - cargoTotal
                                    end
                                end

                                if cargoTotal >= limit or step <= 0 then
                                    eGlobal.Business.Hangar.Cargo.Total:Set(eStat.MPX_HANGAR_CONTRABAND_TOTAL:Get())
                                    SilentLogger.LogInfo("[Pocket Dimension (Hangar)] Cargo limit should've been reached ツ")
                                    ftr:Toggle(false)
                                    return
                                end
                            end

                            eGlobal.Business.Hangar.Cargo.Type:Set(type)
                            eGlobal.Business.Hangar.Cargo.Amount:Set(step)
                            eGlobal.Business.Hangar.Cargo.Total:Set(0)
                            ePackedStat.Business.Hangar.Cargo:Set(true)

                            if not loggedHangarStart then
                                ftr:SetName("Stop")
                                ftr:SetDesc("Stops filling your Hangar stock repeatedly.")
                                SilentLogger.LogInfo("[Start (Hangar)] Deeper supplier should've been enabled ツ")
                                loggedHangarStart  = true
                                PD_REMOVE_DISABLED = true
                            end

                            Script.Yield(math.floor(delay * 1000))

                            if not CONFIG.pocket_dimension.validation then return end

                            while eNative.NETSHOPPING.NET_GAMESERVER_TRANSACTION_IN_PROGRESS() do
                                Script.Yield()
                            end
                        end
                    },

                    CustomDelay = {
                        hash = J("SN_Hangar_CustomDelay"),
                        name = "?",
                        type = eFeatureType.Button,
                        desc = "Why are you reading this description? Dummy.",
