--#region EventMgr

local onPresentEventId       = nil
local onUnloadEventId        = nil
local friendsWhitelisted     = true
local teamWhitelisted        = true
local eventProtectionEnabled = false

function EventMgr.OnPresent()
    onPresentEventId = EventMgr.RegisterHandler(eLuaEvent.ON_PRESENT, function()
        if not CONFIG.compatibility_mode then return end

        if not FeatureMgr.GetFeatureByHash(eTable.Cherax.Features.ProtectionWhitelist):IsListIndexToggled(0) then
            friendsWhitelisted = false
        end

        if not FeatureMgr.GetFeatureByHash(eTable.Cherax.Features.ProtectionWhitelist):IsListIndexToggled(1) then
            teamWhitelisted = false
        end

        if FeatureMgr.GetFeatureByHash(eTable.Cherax.Features.EventProtection):IsToggled() then
            eventProtectionEnabled = true
        end

        FeatureMgr.GetFeatureByHash(eTable.Cherax.Features.ProtectionWhitelist):ToggleListIndex(0, true)
        FeatureMgr.GetFeatureByHash(eTable.Cherax.Features.ProtectionWhitelist):ToggleListIndex(1, true)
        FeatureMgr.GetFeatureByHash(eTable.Cherax.Features.EventProtection):Toggle(false)
    end)
end

function EventMgr.OnUnload()
    onUnloadEventId = EventMgr.RegisterHandler(eLuaEvent.ON_UNLOAD, function()
        local rootTab = ListGUI.GetRootTab()
        if not rootTab then return end

        local scriptTab = rootTab:GetSubTab(F("%s v%s %s", SCRIPT_NAME, SCRIPT_VER, GTA_EDITION))
        if not scriptTab then return end

        rootTab:RemoveSubTab(scriptTab)

        EventMgr.RemoveHandler(onPresentEventId)
        SilentLogger.LogInfo(F("%s has unloaded ツ", SCRIPT_NAME))

        if CONFIG.compatibility_mode then
            FeatureMgr.GetFeatureByHash(eTable.Cherax.Features.ProtectionWhitelist):ToggleListIndex(0, friendsWhitelisted)
            FeatureMgr.GetFeatureByHash(eTable.Cherax.Features.ProtectionWhitelist):ToggleListIndex(1, teamWhitelisted)
            FeatureMgr.GetFeatureByHash(eTable.Cherax.Features.EventProtection):Toggle(eventProtectionEnabled)
        end
    end)
end

EventMgr.OnUnload()
EventMgr.OnPresent()

--#endregion

--#region FeatureMgr

_GetFeature          = FeatureMgr.GetFeature
_GetFeatureListIndex = FeatureMgr.GetFeatureListIndex
_GetFeatureInt       = FeatureMgr.GetFeatureInt
_AddFeature          = FeatureMgr.AddFeature

function FeatureMgr.GetFeature(feature)
    return _GetFeature(feature.hash)
end

function FeatureMgr.GetFeatureByHash(hash)
    return _GetFeature(hash)
end

function FeatureMgr.GetFeatureListIndex(feature)
    return _GetFeatureListIndex(feature.hash)
end

function FeatureMgr.GetFeatureInt(feature)
    return _GetFeatureInt(feature.hash)
end

function FeatureMgr.GetFeatureBool(feature)
    return _GetFeature(feature.hash):IsToggled()
end

featureHashes = {}

function FeatureMgr.AddFeature(feature, callback)
    _AddFeature(feature.hash, feature.name, feature.type, feature.desc, function(f)
        if callback then
            callback(f)
        elseif feature.func then
            feature.func(f)
        end
    end)

    if feature.list then
        FeatureMgr.GetFeature(feature):SetList(feature.list:GetNames())
    end

    if feature.defv then
        FeatureMgr.GetFeature(feature):SetDefaultValue(feature.defv)
    end

    if feature.lims then
        FeatureMgr.GetFeature(feature):SetLimitValues(U(feature.lims))
    end

    if feature.step then
        FeatureMgr.GetFeature(feature):SetStepSize(feature.step)
    end

    if feature.defv or feature.lims or feature.step then
        FeatureMgr.GetFeature(feature):Reset()
    end

    I(featureHashes, feature.hash)

    return FeatureMgr.GetFeature(feature)
end

function FeatureMgr.AddLoop(feature, onEnable, onDisable)
    local state = false

    FeatureMgr.AddFeature(feature, function(f)
        if f:IsToggled() then
            if not state then
                state = true

                Script.RegisterLooped(function()
                    if ShouldUnload() or not f:IsToggled() then
                        return
                    end

                    if onEnable then
                        onEnable(f)
                        Script.Yield()
                    elseif feature.func then
                        feature.func(f)
                    end

                    Script.Yield()
                end)
            end
        elseif onDisable and state then
            onDisable(f)
            state = false
        end
    end)

    return FeatureMgr.GetFeature(feature)
end

--#endregion

--#region Bits

Bits = {}

function Bits.GetBit(value, position)
	return (value >> position) & 1
end

function Bits.SetBit(value, position)
    return value | (1 << position)
end

function Bits.IsBitSet(value, position)
	return (value & (1 << position)) ~= 0
end

function Bits.ClearBit(value, position)
	return value & ~(1 << position)
end

function Bits.ToggleBit(value, position)
	return value ~ (1 << position)
end

function Bits.SetBits(value, positions)
	for _, position in ipairs(positions) do
		value = Bits.SetBit(value, position)
	end
	return value
end

function Bits.IsAnyBitSet(value, positions)
	for _, position in ipairs(positions) do
		if Bits.IsBitSet(value, position) then
			return true
		end
	end
	return false
end

function Bits.ClearBits(value, positions)
	for _, position in ipairs(positions) do
		value = Bits.ClearBit(value, position)
	end
	return value
end

function Bits.ToggleBits(value, positions)
	for _, position in ipairs(positions) do
		value = Bits.ToggleBit(value, position)
	end
	return value
end

