FeatureMgr.AddFeature(eFeature.Business.Hangar.Supplies.PocketDimension.Toggle, function(f)
    eFeature.Business.Hangar.Supplies.PocketDimension.Toggle.func(f)
    if Script.IsStandardEdition() then return end

    if f:IsToggled() then
        FeatureMgr.GetFeature(eFeature.Business.Hangar.Supplies.Supply):SetVisible(false)
        FeatureMgr.GetFeature(eFeature.Business.Hangar.Supplies.Supplier)
                :SetVisible(false)
                :Toggle(false)

        if CONFIG.pocket_dimension.method == 0 then
            FeatureMgr.GetFeature(eFeature.Business.Hangar.Supplies.PocketDimension.StartStop):SetVisible(true)
            FeatureMgr.GetFeature(eFeature.Business.Hangar.Supplies.PocketDimension.CustomDelay):SetVisible(true)
            FeatureMgr.GetFeature(eFeature.Business.Hangar.Supplies.PocketDimension.CustomLimit):SetVisible(true)
            FeatureMgr.GetFeature(eFeature.Business.Hangar.Supplies.PocketDimension.CustomStep):SetVisible(true)
            FeatureMgr.GetFeature(eFeature.Business.Hangar.Supplies.PocketDimension.CustomType):SetVisible(true)
        else
            FeatureMgr.GetFeature(eFeature.Business.Hangar.Supplies.PocketDimension.Fill):SetVisible(true)
            FeatureMgr.GetFeature(eFeature.Business.Hangar.Supplies.PocketDimension.Filter)
                :SetVisible(true)
                :SetListIndex(0)
            FeatureMgr.GetFeature(eFeature.Business.Hangar.Supplies.PocketDimension.Limit)
                :SetVisible(true)
                :SetIntValue(eStat.MPX_HANGAR_CONTRABAND_TOTAL:Get() + 50)
        end

        FeatureMgr.GetFeature(eFeature.Business.Hangar.Supplies.PocketDimension.Remove):SetVisible(true)
        FeatureMgr.GetFeature(eFeature.Business.Hangar.Supplies.PocketDimension.Session):SetVisible(true)
    else
        FeatureMgr.GetFeature(eFeature.Business.Hangar.Supplies.Supply):SetVisible(true)
        FeatureMgr.GetFeature(eFeature.Business.Hangar.Supplies.Supplier):SetVisible(true)
        FeatureMgr.GetFeature(eFeature.Business.Hangar.Supplies.PocketDimension.Fill):SetVisible(false)
        FeatureMgr.GetFeature(eFeature.Business.Hangar.Supplies.PocketDimension.Remove):SetVisible(false)
        FeatureMgr.GetFeature(eFeature.Business.Hangar.Supplies.PocketDimension.Session):SetVisible(false)
        FeatureMgr.GetFeature(eFeature.Business.Hangar.Supplies.PocketDimension.StartStop)
            :SetVisible(false)
            :Toggle(false)

        FeatureMgr.GetFeature(eFeature.Business.Hangar.Supplies.PocketDimension.CustomDelay):SetVisible(false)
        FeatureMgr.GetFeature(eFeature.Business.Hangar.Supplies.PocketDimension.CustomLimit):SetVisible(false)
        FeatureMgr.GetFeature(eFeature.Business.Hangar.Supplies.PocketDimension.Filter)
            :SetVisible(false)
            :SetListIndex(0)
        FeatureMgr.GetFeature(eFeature.Business.Hangar.Supplies.PocketDimension.Limit)
            :SetVisible(false)
            :SetIntValue(eStat.MPX_HANGAR_CONTRABAND_TOTAL:Get() + 50)

        FeatureMgr.GetFeature(eFeature.Business.Hangar.Supplies.PocketDimension.CustomStep):SetVisible(false)
        FeatureMgr.GetFeature(eFeature.Business.Hangar.Supplies.PocketDimension.Step)
            :SetVisible(false)
            :SetIntValue(50)

        FeatureMgr.GetFeature(eFeature.Business.Hangar.Supplies.PocketDimension.CustomType):SetVisible(false)
        FeatureMgr.GetFeature(eFeature.Business.Hangar.Supplies.PocketDimension.Type)
            :SetVisible(false)
            :SetListIndex(0)
    end
end)

FeatureMgr.AddLoop(eFeature.Business.Hangar.Supplies.PocketDimension.StartStop, function(f)
    local limitToggled  = not FeatureMgr.GetFeature(eFeature.Business.Hangar.Supplies.PocketDimension.CustomLimit):IsVisible()
    local limitByAmount = FeatureMgr.GetFeature(eFeature.Business.Hangar.Supplies.PocketDimension.Filter):GetListIndex() == 0
    local limit         = FeatureMgr.GetFeature(eFeature.Business.Hangar.Supplies.PocketDimension.Limit):GetIntValue()
    local type          = FeatureMgr.GetFeature(eFeature.Business.Hangar.Supplies.PocketDimension.Type):GetListIndex()
    local step          = FeatureMgr.GetFeature(eFeature.Business.Hangar.Supplies.PocketDimension.Step):GetIntValue()
    local delay         = FeatureMgr.GetFeature(eFeature.Settings.PocketDimension.Delay):GetFloatValue()
    eFeature.Business.Hangar.Supplies.PocketDimension.StartStop.func(f, limitToggled, limitByAmount, limit, step, type, delay)
end, function(f)
    eFeature.Business.Hangar.Supplies.PocketDimension.StartStop.func(f, false, false, 0, 0, 0, 0)
end)
    :SetVisible(false)

FeatureMgr.AddFeature(eFeature.Business.Hangar.Supplies.PocketDimension.Fill, function(f)
    local limitByAmount = FeatureMgr.GetFeature(eFeature.Business.Hangar.Supplies.PocketDimension.Filter):GetListIndex() == 0
    local limit         = FeatureMgr.GetFeature(eFeature.Business.Hangar.Supplies.PocketDimension.Limit):GetIntValue()
    local type          = FeatureMgr.GetFeature(eFeature.Business.Hangar.Supplies.PocketDimension.Type):GetListIndex()
    eFeature.Business.Hangar.Supplies.PocketDimension.Fill.func(limitByAmount, limit, type)
end)
    :SetVisible(false)

